"""Regenerate the graph reachability heatmap (PDF + PNG) from saved results."""

import numpy as np
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt

TEST_HOPS  = [1, 2, 3, 4, 6, 8, 10, 12]
TEST_STEPS = [1, 2, 3, 5, 8, 12, 15, 20]

# Final-run accuracy grid (1-5 hop training, d=128), as reported in the paper.
# Regenerated by graph_experiment.py at train time; transcribed here so the
# styled PDF can be rebuilt without retraining.
results = np.array([
    [0.97, 0.97, 1.00, 1.00, 1.00, 1.00, 1.00, 1.00],  # hops=1
    [0.51, 0.98, 1.00, 1.00, 1.00, 1.00, 1.00, 1.00],  # hops=2
    [0.51, 0.54, 1.00, 1.00, 1.00, 1.00, 1.00, 1.00],  # hops=3
    [0.52, 0.54, 0.50, 1.00, 1.00, 1.00, 1.00, 1.00],  # hops=4
    [0.50, 0.52, 0.50, 0.50, 1.00, 1.00, 1.00, 1.00],  # hops=6
    [0.51, 0.54, 0.50, 0.50, 0.50, 0.97, 1.00, 1.00],  # hops=8
    [0.51, 0.52, 0.50, 0.50, 0.50, 0.50, 0.50, 0.50],  # hops=10
    [0.51, 0.53, 0.50, 0.50, 0.50, 0.50, 0.50, 0.50],  # hops=12
])

TRAIN_HOP_RANGE  = (1, 5)
TRAIN_STEP_RANGE = (5, 8)
TEST_ID_HOPS     = [1, 2, 3, 4]

# Font sizes below are deliberately oversized: the figure is scaled to about 0.35x
# in a two-column layout, so at final size the on-page text lands near 8pt.
fig, ax = plt.subplots(figsize=(10, 7))
im = ax.imshow(results, cmap="RdYlGn", vmin=0.4, vmax=1.0, aspect="auto")

ax.set_xticks(range(len(TEST_STEPS)))
ax.set_xticklabels(TEST_STEPS)
ax.set_yticks(range(len(TEST_HOPS)))
ax.set_yticklabels(TEST_HOPS)
ax.tick_params(axis="both", labelsize=20)
ax.set_xlabel("Thinking Steps (Compute Depth)", fontsize=23)
ax.set_ylabel("Path Hops (Task Difficulty)", fontsize=23)
# Horizontal line: hop ID/OOD boundary (task difficulty).
# Region labels sit in the right margin, outside the heatmap cells.
id_ood_boundary = len(TEST_ID_HOPS) - 0.5
ax.axhline(y=id_ood_boundary, color="white", linewidth=2.5, linestyle="--")
_yax = ax.get_yaxis_transform()
_id_center  = (-0.5 + id_ood_boundary) / 2
_ood_center = (id_ood_boundary + len(TEST_HOPS) - 0.5) / 2
ax.text(1.015, _id_center, "ID", transform=_yax, ha="left", va="center",
        fontsize=21, color="red", fontweight="bold", clip_on=False)
ax.text(1.015, _ood_center, "OOD", transform=_yax, ha="left", va="center",
        fontsize=21, color="red", fontweight="bold", clip_on=False)

# Vertical lines: step ID/OOD boundaries. Region labels sit above the heatmap.
step_left  = next(i for i, s in enumerate(TEST_STEPS) if s >= TRAIN_STEP_RANGE[0]) - 0.5
step_right = next(i for i, s in enumerate(TEST_STEPS) if s >  TRAIN_STEP_RANGE[1]) - 0.5
ax.axvline(x=step_left,  color="white", linewidth=2.5, linestyle="--")
ax.axvline(x=step_right, color="white", linewidth=2.5, linestyle="--")
_xax = ax.get_xaxis_transform()
ax.text(step_left / 2 - 0.25, 1.03, "OOD", transform=_xax, ha="center", va="bottom",
        fontsize=21, color="red", fontweight="bold", clip_on=False)
ax.text((step_left + step_right) / 2, 1.03, "ID", transform=_xax, ha="center", va="bottom",
        fontsize=21, color="red", fontweight="bold", clip_on=False)
ax.text((step_right + len(TEST_STEPS) - 0.5) / 2, 1.03, "OOD", transform=_xax,
        ha="center", va="bottom", fontsize=21, color="red", fontweight="bold", clip_on=False)

for i in range(len(TEST_HOPS)):
    for j in range(len(TEST_STEPS)):
        val = results[i, j]
        color = "white" if val < 0.6 else "black"
        ax.text(j, i, f"{val:.2f}", ha="center", va="center",
                fontsize=19, color=color)

cbar = fig.colorbar(im, ax=ax, shrink=0.8, pad=0.10)
cbar.set_label("Accuracy", fontsize=23)
cbar.ax.tick_params(labelsize=20)

plt.tight_layout(rect=[0, 0, 1, 0.92])
out = "graph_results.pdf"
plt.savefig(out, dpi=150)
plt.savefig(out.replace(".pdf", ".png"), dpi=150)
print(f"Saved to {out} (+ .png)")
